import { useAuth } from "@/_core/hooks/useAuth";
import { permittedPath } from "@/components/DashboardLayout";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { trpc } from "@/lib/trpc";
import { runAttendanceStaffAction, runLeaveStaffAction } from "../lib/hrValidation";
import { AlertTriangle, CalendarDays, CheckCircle2, Clock3, Copy, Droplets, ExternalLink, MessageCircle, Printer, Search, Ticket, Umbrella, UsersRound } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
